
SELECT id, 'seed-admin', 'APPROVE', 'Business email and registration matched.', NOW() - INTERVAL '14 days'
FROM recruiter_submissions WHERE company_name = 'Acme Staffing';

SELECT id, 'seed-admin', 'REJECT', 'Could not validate the supplied registration details.', NOW() - INTERVAL '17 days'
FROM recruiter_submissions WHERE company_name = 'Nimbus Talent';
